<?php
require __DIR__.'/../cms/config.php'; require_login(); $u=current_user();$students=read_json('students');$results=read_json('results');$subjects=read_json('subjects');$attendance=read_json('attendance');$classes=read_json('classes');
$id=(int)($_GET['student_id']??0);if($u['role']==='student')$id=(int)$u['profile_id'];
if($u['role']==='parent'){ $ok=false;foreach($students as $s)if((int)$s['id']===$id&&(int)($s['parent_id']??0)===(int)$u['profile_id'])$ok=true;if(!$ok)$id=0; }
if(in_array($u['role'],['admin','teacher'],true)){}elseif(!$id){http_response_code(403);exit('Access denied.');}
$st=null;foreach($students as $s)if((int)$s['id']===$id){$st=$s;break;}if(!$st)exit('Student not found.');
function rn($a,$id){foreach($a as $x)if((int)$x['id']===(int)$id)return $x['name']??'—';return '—';}
$term=$_GET['term']??'All Terms';$rows=array_values(array_filter($results,fn($r)=>(int)$r['student_id']===$id&&($term==='All Terms'||($r['term']??'')===$term)));
$att=array_values(array_filter($attendance,fn($a)=>(int)$a['student_id']===$id));$present=count(array_filter($att,fn($a)=>in_array($a['status']??'', ['Present','Late'],true)));$rate=count($att)?round($present/count($att)*100,1):null;
?><!doctype html><html><head><meta charset="utf-8"><title>Report Card — <?=h($st['name'])?></title><style>@page{size:A4;margin:16mm}body{font-family:Arial,sans-serif;color:#17231f;margin:0}.head{border-bottom:3px solid #b28b45;padding-bottom:16px;margin-bottom:24px}.brand{letter-spacing:.25em;color:#b28b45;font-weight:700}.student{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:18px 0}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:9px;border:1px solid #d9ded9;text-align:left}.table th{background:#eef1ed}.summary{margin-top:24px;display:flex;gap:40px}.no-print{margin-bottom:20px}@media print{.no-print{display:none}}</style><link rel="stylesheet" href="assets/dynamic-site.css">
</head><body class="rf-dynamic"><div class="no-print"><button onclick="window.print()">Print / Save PDF</button></div><div class="head"><div class="brand">R I D G E F I E L D &nbsp; A C A D E M Y</div><h1>Academic Report</h1><p>Official learner progress summary</p></div><div class="student"><div><strong>Learner:</strong> <?=h($st['name'])?></div><div><strong>Student No:</strong> <?=h($st['student_no']??'')?></div><div><strong>Grade:</strong> <?=h($st['grade']??'')?></div><div><strong>Class:</strong> <?=h(rn($classes,(int)($st['class_id']??0)))?></div><div><strong>Term:</strong> <?=h($term)?></div><div><strong>Attendance:</strong> <?=h($rate===null?'—':$rate.'%')?></div></div><table class="table"><tr><th>Subject</th><th>Assessment</th><th>Term</th><th>Mark</th><th>Percentage</th><th>Comment</th></tr><?php foreach($rows as $r):$p=$r['out_of']?(float)$r['mark']/$r['out_of']*100:0;?><tr><td><?=h(rn($subjects,(int)$r['subject_id']))?></td><td><?=h($r['assessment']??'')?></td><td><?=h($r['term']??'')?></td><td><?=h((string)$r['mark'])?>/<?=h((string)$r['out_of'])?></td><td><?=number_format($p,1)?>%</td><td><?=h($r['comment']??'')?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6">No results have been recorded.</td></tr><?php endif;?></table><div class="summary"><div><strong>Generated:</strong> <?=date('d F Y')?></div><div><strong>Attendance:</strong> <?=h($rate===null?'Not available':$rate.'%')?></div></div><script src="assets/dynamic-site.js"></script>
</body></html>